import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {pathToFileURL} from 'node:url';import assert from 'node:assert/strict';
const outDir='evidence/audit-followup-20261026',label=['live','final'].includes(process.argv[2])?process.argv[2]:'snapshot',source=label==='live'?'.':outDir+(label==='final'?'/snapshot-final':'/snapshot');
const {Simulation}=await import(pathToFileURL(path.resolve(source,'shared/simulation.js'))),{defaults,contractType,clone}=await import(pathToFileURL(path.resolve(source,'shared/config.js')));
const out={at:new Date().toISOString(),source:label,checks:[],attacks:[],observations:[],sourceHashes:Object.fromEntries(['shared/navigation.js','shared/simulation.js','shared/skill5-mechanics.js','shared/manual-target.js','shared/hero-rules.js'].map(f=>[f,crypto.createHash('sha256').update(fs.readFileSync(path.join(source,f))).digest('hex')]))};
const near=(a,b,m='')=>assert.ok(Math.abs(a-b)<1e-5,`${m}: ${a} != ${b}`),advance=(s,t)=>{const end=s.time+t;while(s.time<end-1e-8)s.tick(Math.min(.05,end-s.time));};
function check(name,fn){try{out.checks.push({name,status:'PASS',evidence:structuredClone(fn())});}catch(e){out.checks.push({name,status:'FAIL',error:e.message,stack:e.stack});}}
function arena(id=0){const s=new Simulation();s.units=[];s.player.retired=true;s.waveAt=1e9;for(const t of s.towers){t.x=100;t.cd=1e9;}
 const troop=(side,x=0,y=3,type='melee')=>{const u=s.spawn(side,type,0,1,x);Object.assign(u,{x,y,hp:1e7,maxHp:1e7,speed:0,cd:1e9});return u;};
 const hero=(cid,x=0,y=0)=>{const p=s.makePlayer(cid===3?1:0,false);p.classId=cid;p.level=12;p.builds[cid]=[1,1,1,1];const h=troop(p.side,x,y,contractType(cid));s.contract(p,h.id);Object.assign(h,{hp:1e7,maxHp:1e7,speed:0,cd:1e9});return {p,h};};const {p,h}=hero(id);s.localPlayerId=p.id;return {s,p,h,troop,hero};}
// Record server shots and HP changes, independently of animation/lastAttackAt.
const actors=[...[0,2,3,4,5].map(id=>({name:'hero-'+id,id,side:id===3?1:0})),...[0,1].flatMap(side=>(side?['melee','ranged']:['melee','ranged','siege']).map(type=>({name:`troop-${side}-${type}`,side,type})))];
const vectors=[[0,1],[0,-1],[.6,.8],[-.6,.8],[.6,-.8],[.8,.6],[Math.SQRT1_2,Math.SQRT1_2]];
for(const actor of actors)for(const [vx,vy]of vectors)for(const gate of ['none','cooldown','cast','channel','stun'])for(const mode of actor.id==null?['auto']:['auto','enemy','friend']){
 const {s,p,h:base,troop}=arena(actor.id??0);let h=base;if(actor.id==null){s.units=[];h=troop(actor.side,0,0,actor.type);Object.assign(h,clone(defaults.troops[actor.type]));h.side=actor.side;h.hp=h.maxHp=1e7;}h.speed=actor.id==null?defaults.troops[actor.type].speed:defaults.heroes[actor.id].speed;h.cd=gate==='cooldown'?.6:0;h.x=vx>.7?-2:vx<-.7?2:0;h.y=0;
 if(['cast','channel','stun'].includes(gate))h[gate==='cast'?'castUntil':gate==='channel'?'channelUntil':'stunUntil']=.6;
 const chaseGap=mode==='enemy'?3:Math.min(3,Math.max(.1,h.aggro-h.range-.2));const e=troop(1-h.side,h.x+vx*(h.range+chaseGap),vy*(h.range+chaseGap));h.targetId=e.id;
 if(mode!=='auto'){assert.ok(s.setManualTarget(e.id,p));if(mode==='friend'){const f=troop(h.side,-4,0);const accepted=s.setManualTarget(f.id,p);assert.equal(accepted,[0,5].includes(actor.id));}}
 const hits=[],shots=[],damage=s.damage.bind(s),projectile=s.projectile.bind(s);s.damage=function(a,t,n,basic,...rest){const before=t.hp,value=damage(a,t,n,basic,...rest);if(a?.id===h.id&&basic)hits.push({time:this.time,amount:before-t.hp,targetId:t.id});return value;};s.projectile=function(a,t,...args){if(a.id===h.id)shots.push({time:this.time,targetId:t.id});return projectile(a,t,...args);};
 const trace=[];const duration=chaseGap/h.speed+(gate==='none'?0:.6)+h.interval+2;for(let i=0;i<Math.ceil(duration/.05);i++){s.tick(.05);if(i%10===0)trace.push({time:s.time,x:h.x,y:h.y,distance:Math.hypot(e.x-h.x,e.y-h.y),cd:h.cd,lastAttackAt:h.lastAttackAt??null,hp:e.hp});}
 const gap=Math.hypot(e.x-h.x,e.y-h.y)-h.range;out.attacks.push({actor:actor.name,side:actor.side,vector:[vx,vy],gate,mode,status:hits.length?'PASS':'FAIL',range:h.range,gap,end:s.time,firstShot:shots[0]??null,firstHit:hits[0]??null,hits:hits.length,shots:shots.length,lastAttackAt:h.lastAttackAt??null,enemyDamage:1e7-e.hp,manualTargetId:h.manualTargetId,targetId:h.targetId,trace});
}
for(const id of [0,2,3,4,5])for(let skill=0;skill<4;skill++)check(`class${id}/skill${skill+1}/cast-gates-double-budget-death-cancel`,()=>{const {s,p,h,troop,hero}=arena(id),e=hero(id===3?0:3,0,3).h,f=troop(h.side,1,0);e.targetId=f.id;f.hp=1e6;h.hp=h.maxHp*.4;if(id===5&&skill===2)s.debuff(f,e,'moveSlow',.2,6,null,true);h.targetId=e.id;const rank=p.builds[id][skill];p.builds[id][skill]=0;assert.equal(s.castPlan(skill).code,'locked');p.builds[id][skill]=rank;const cost=skill===3?3:1;p.stamina=cost-.01;assert.equal(s.castPlan(skill).code,'stamina');p.stamina=100;h.stunUntil=1;assert.equal(s.castPlan(skill).code,'stunned');h.stunUntil=0;assert.ok(s.cast(skill),s.notice);assert.equal(s.cast(skill),false);near(p.stamina,100-cost);near(p.cd[skill],[5,10,15,30][skill]);const v=s.skillValues.at(-1);near(v.base,h.attack*16*cost);near(v.limit,h.attack*20*cost);s.damage(null,h,1e9);const before=e.hp;advance(s,2);near(e.hp,before);return {cost,base:v.base,limit:v.limit};});
for(const [id,skill,coefficient,wait]of [[0,0,12,.4],[2,1,12,1],[2,2,13.6,3.5],[2,3,36,1],[3,0,3.2,.4],[3,1,2.4,1.3],[3,2,.4,1.4],[4,0,16,.4],[4,1,16,.4],[4,2,16,.4],[4,3,16,.4],[5,0,6,.4]])check(`class${id}/skill${skill+1}/actual-base-damage`,()=>{const {s,p,h,troop}=arena(id),e=troop(1-h.side,0,3);h.targetId=e.id;assert.ok(s.cast(skill));const hp=e.hp;advance(s,wait);near(hp-e.hp,h.attack*coefficient);return {attack:h.attack,damage:hp-e.hp,coefficient};});
for(const id of [0,2,3,4,5])for(const skill of id===0?[0]:id===2?[0,1,2,3]:id===3?[0,1]:id===4?[0,1,2,3]:[0])check(`class${id}/skill${skill+1}/manual-enemy-and-next-cast-lock`,()=>{const {s,p,h,troop}=arena(id),a=troop(1-h.side,0,2),b=troop(1-h.side,1,3);b.hp=5e6;h.targetId=a.id;assert.ok(s.setManualTarget(b.id,p));const plan=s.castPlan(skill);assert.ok(plan.ok);assert.equal(plan.t.id,b.id);assert.ok(s.cast(skill));assert.ok(s.setManualTarget(a.id,p));advance(s,.4);if(id===2){const payload=s.fields.find(f=>f.kind==='runeBarrage')||s.projectiles.find(x=>x.payload);assert.ok(payload);assert.equal(payload.preferredTargetId??payload.payload?.preferredTargetId,b.id);}else if(id===3&&skill===1){advance(s,.4);assert.equal(h.dash.preferredTargetId,b.id);}else assert.ok(b.hp<5e6);return {beforeTarget:b.id,nextTarget:a.id,locked:plan.t.id};});
for(const id of [0,5])check(`class${id}/manual-friend-does-not-replace-offensive-skill-or-hurt-ally`,()=>{const {s,p,h,troop}=arena(id),e=troop(1-h.side,0,2),f=troop(h.side,1,1);h.targetId=e.id;const fhp=f.hp;assert.ok(s.setManualTarget(f.id,p));assert.equal(s.castPlan(0).t.id,e.id);assert.ok(s.cast(0));advance(s,.4);assert.ok(e.hp<1e7);assert.ok(f.hp>=fhp);return {foeDamage:1e7-e.hp,friendDelta:f.hp-fhp};});
check('orc roar keeps self-centered 6 range and 3 other allies while preferring manual',()=>{const {s,p,h,troop}=arena(0),nearby=Array.from({length:4},(_,i)=>troop(0,i*.2,1)),chosen=troop(0,0,6),outside=troop(0,0,6.01);s.setManualTarget(chosen.id,p);const plan=s.castPlan(1);assert.equal(plan.t.id,h.id);assert.equal(plan.targets.length,4);assert.equal(plan.targets[0].id,h.id);assert.equal(plan.targets[1].id,chosen.id);s.cast(1);advance(s,.4);assert.ok(chosen.guards.length);assert.ok(!outside.guards?.length);return {ids:plan.targets.map(u=>u.id)};});
check('orc rescue friend requires in-range enemy hero attacking friend, no tower/invalid override',()=>{const {s,p,h,troop,hero}=arena(0),f=troop(0,0,10),e=hero(3,0,13).h;e.targetId=f.id;s.setManualTarget(f.id,p);assert.equal(s.castPlan(2).t.id,f.id);e.y=14.01;assert.equal(s.castPlan(2).ok,false);e.y=13;e.targetId=h.id;assert.equal(s.castPlan(2).ok,false);e.targetId=f.id;s.cast(2);advance(s,.4);near(h.y,10);near(f.y,0);near(h.guards.at(-1).ratio,.5);return {hY:h.y,fY:f.y};});
