check('elf link shared effective heals are 200%, bidirectional nonrecursive, self/tower excluded',()=>{const {s,p,h,troop}=arena(5),f=troop(0,0,12);h.hp=f.hp=1000;s.setManualTarget(f.id,p);s.cast(1);advance(s,.4);const v=s.skillValues.at(-1);s.heal(h,100,h);near(h.hp,1100);near(f.hp,1200);s.heal(f,50,h);near(h.hp,1200);near(f.hp,1250);near(v.spent,300);return {value:v.spent};});
check('elf attack side heal preserves enemy center5, cap3, preferred friend can be17 from caster',()=>{const {s,p,h,troop}=arena(5),e=troop(1,0,12);h.targetId=e.id;const crowd=Array.from({length:4},(_,i)=>troop(0,i*.1,12)),f=troop(0,0,17),outside=troop(0,0,17.01);for(const u of [h,...crowd,f,outside])u.hp=1000;s.setManualTarget(f.id,p);s.cast(0);advance(s,.4);const healed=[...crowd,f,outside].filter(u=>u.hp>1000);assert.equal(healed.length,3);assert.ok(healed.includes(f));assert.ok(!healed.includes(outside));near(healed.reduce((n,u)=>n+u.hp-1000,0),h.attack*10);return {healed:healed.map(u=>u.id)};});
