check('elf group heal self+4, preferred friend, 960% each, original radius12',()=>{const {s,p,h,troop}=arena(5),nearby=Array.from({length:5},(_,i)=>troop(0,i*.2,1)),f=troop(0,0,12),outside=troop(0,0,12.01);for(const u of[h,...nearby,f,outside])u.hp=1000;s.setManualTarget(f.id,p);const plan=s.castPlan(3);assert.equal(plan.targets.length,5);assert.ok(plan.targets.includes(h)&&plan.targets.includes(f));s.cast(3);advance(s,.4);const healed=[h,...nearby,f,outside].filter(u=>u.hp>1000);assert.equal(healed.length,5);for(const u of healed)near(u.hp-1000,h.attack*9.6);return {healed:healed.map(u=>u.id)};});
