check('several frost hits do not multiply current attack cooldown beyond one40% slow',()=>{const {s,p,h,troop,hero}=arena(2),e=troop(1,0,3),r2=hero(2,1,0),r3=hero(2,-1,0);e.cd=2.8;e.speed=0;h.targetId=r2.h.targetId=r3.h.targetId=e.id;for(const x of[p,r2.p,r3.p])s.cast(1,x);advance(s,.7);const evidence={time:s.time,cd:e.cd,remaining:e.cd-s.time,activeSlow:s.activeDebuffs(e,'attackSpeedDown').map(x=>x.ratio),until:Object.values(e.debuffs).map(x=>x.until)};out.observations.push({name:'frost-cooldown-stack',...evidence});assert.ok(e.cd<=4.5,JSON.stringify(evidence));return evidence;});
for(const[id,skills]of[[0,[0,2]],[2,[0,1,2,3]],[3,[0,1]],[4,[0,1,2,3]],[5,[0,1,2,3]]])for(const skill of skills)check(`class${id}/skill${skill+1}/orthogonal-range-edge-and-outside`,()=>{const {s,p,h,troop,hero}=arena(id),range=s.config.heroes[id].skills[skill].targetRange;let e;if(id===0&&skill===2){e=hero(3,0,range).h;const f=troop(0,1,0);e.targetId=f.id;}else if(id===5&&skill>0){e=troop(0,0,range);e.hp=1000;if(skill===2)s.debuff(e,h,'moveSlow',.3,10,null,true);}else e=troop(1-h.side,0,range);h.targetId=e.side===h.side?null:e.id;assert.ok(s.castPlan(skill).ok,s.castPlan(skill).reason);e.y=range+.001;assert.equal(s.castPlan(skill).ok,false);return {range,inside:true,outside:false};});
for(const id of[0,2,3,4,5])check(`class${id}/manual-selection20-boundary-and-invalid-retains-lock`,()=>{const {s,p,h,troop}=arena(id),e=troop(1-h.side,0,20),friend=troop(h.side,0,20);assert.ok(s.setManualTarget(e.id,p));e.y=20.001;assert.equal(s.setManualTarget(e.id,p),false);assert.equal(h.manualTargetId,e.id);e.y=20;if([0,5].includes(id)){assert.ok(s.setManualTarget(friend.id,p));assert.ok(s.setManualTarget(h.id,p));}else{assert.equal(s.setManualTarget(friend.id,p),false);assert.equal(s.setManualTarget(h.id,p),false);assert.equal(h.manualTargetId,e.id);}return {boundary:20,friendAllowed:[0,5].includes(id)};});
check('orc vulnerable4s and guard5s50percent rescue4s expire independently',()=>{const {s,h,troop,hero}=arena(0),e=hero(3,0,3).h,friend=troop(0,1,0);e.targetId=friend.id;s.cast(0);advance(s,.4);assert.equal(s.activeDebuffs(e,'vulnerable').length,1);advance(s,4);assert.equal(s.activeDebuffs(e,'vulnerable').length,0);s.cast(1);advance(s,.4);near(h.guards.at(-1).ratio,.4);advance(s,5.1);assert.equal(h.guards.length,0);s.cast(2);advance(s,.4);near(h.guards.at(-1).ratio,.5);advance(s,4.1);assert.equal(h.guards.length,0);return {vulnerable:4,roar:5,rescue:4};});
check('elf link duration6 expires and cleanse recognises paid slow but excludes reward mark',()=>{const {s,p,h,troop}=arena(5),friend=troop(0,1,0);s.cast(1);advance(s,.4);assert.ok(s.fields.some(f=>f.kind==='link'));advance(s,6.1);assert.equal(s.fields.some(f=>f.kind==='link'),false);s.debuff(friend,h,'moveSlow',.3,10,{limit:1,spent:1,parts:{}},true);assert.ok(s.hasNegative(friend));assert.ok(s.cleanse(friend));assert.equal(s.hasNegative(friend),false);friend.soulMarks=[{ownerId:h.id,until:s.time+5,heat:2}];assert.equal(s.hasNegative(friend),false);s.cleanse(friend);assert.equal(friend.soulMarks.length,1);return {duration:6,paidSlowRemoved:true,rewardRecordRetained:true};});
for(const heat of[0,1,2,3,4,5])check(`fire ult heat${heat} target cap and lowest absolute HP`,()=>{const {s,h,troop}=arena(4),es=Array.from({length:5},(_,i)=>troop(1,i*.2,4));es.forEach((u,i)=>{u.hp=10000+i*1000;u.maxHp=i===0?10001:1e7;});h.heat=heat;h.heatUntil=100;const plan=s.castPlan(3);assert.equal(plan.targets.length,1+Math.floor(heat/2));assert.deepEqual(plan.targets.map(u=>u.id),es.slice(0,1+Math.floor(heat/2)).map(u=>u.id));s.cast(3);advance(s,.4);assert.equal(h.heat,0);return {heat,targets:plan.targets.length};});
check('elf link absolute HP priority differs from ratio priority and never targets buildings',()=>{const {s,p,h,troop}=arena(5),absoluteLow=troop(0,1,0),ratioLow=troop(0,2,0),tower=s.towers[0];Object.assign(absoluteLow,{hp:100,maxHp:1000});Object.assign(ratioLow,{hp:1000,maxHp:1e7});assert.equal(s.castPlan(1).t.id,absoluteLow.id);Object.assign(tower,{side:0,x:0,y:2,hp:1,maxHp:10000});s.setManualTarget(tower.id,p);assert.equal(s.castPlan(1).t.id,absoluteLow.id);assert.ok(!s.castPlan(3).targets.includes(tower));return {target:absoluteLow.id};});
check('lord energy4 minions or1 hero heals4percent, remainder survives, passive not doubled',()=>{const {s,h,troop,hero}=arena(3);h.hp=h.maxHp*.5;for(let i=0;i<3;i++)s.damage(h,troop(0,1,1),1e9);assert.equal(h.energy,3);const hp=h.hp,e=hero(0,1,1).h;s.damage(h,e,1e9);near(h.hp-hp,h.maxHp*.04);assert.equal(h.energy,3);return {healRatio:.04,remainingEnergy:3};});
fs.writeFileSync(`${outDir}/model-${label}.json`,JSON.stringify(out,null,2));console.log(JSON.stringify({source:label,attacks:{total:out.attacks.length,passed:out.attacks.filter(x=>x.status==='PASS').length,failed:out.attacks.filter(x=>x.status==='FAIL').length,firstFailures:out.attacks.filter(x=>x.status==='FAIL').slice(0,6)},checks:{passed:out.checks.filter(x=>x.status==='PASS').length,failed:out.checks.filter(x=>x.status==='FAIL')}},null,2));
